begin;
create extension if not exists pgtap with schema public;
select plan(28);
insert into auth.users(id) values ('a1000000-0000-0000-0000-000000000001'), ('a1000000-0000-0000-0000-000000000002');
insert into public.developer_apps(id, owner_id, name, description, contact_email, privacy_url, client_type, redirect_uris)
values ('a2000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001', 'Test', 'Test application', 'test@example.org', 'https://example.org/privacy', 'public', array['https://example.org/cb']);
select ok(not has_table_privilege('anon', 'public.developer_apps', 'SELECT'), 'anonymous cannot list applications');
select ok(not has_column_privilege('authenticated', 'public.developer_apps', 'secret_hash', 'SELECT'), 'members cannot read credential hashes');
select ok(not has_table_privilege('authenticated', 'public.developer_tokens', 'SELECT'), 'members cannot read tokens');
select ok(not has_table_privilege('authenticated', 'public.developer_codes', 'SELECT'), 'members cannot read codes');
select ok(not has_table_privilege('authenticated', 'public.developer_apps', 'INSERT'), 'direct app registration bypass is denied');
select ok(not has_column_privilege('authenticated', 'public.developer_apps', 'approved_scopes', 'UPDATE'), 'members cannot approve their own scopes');
select ok(not has_table_privilege('authenticated', 'public.developer_grants', 'INSERT'), 'members cannot forge consent grants');
select ok(not has_function_privilege('anon', 'public.developer_review_scope(uuid,boolean,text)', 'EXECUTE'), 'anonymous cannot review');
set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"a1000000-0000-0000-0000-000000000002","role":"authenticated"}', true);
select is((select count(id)::integer from public.developer_apps), 0, 'another member cannot see app metadata');
select throws_ok($$select public.developer_review_scope('a2000000-0000-0000-0000-000000000001', true, 'approved')$$, '42501', null, 'non-admin cannot review');
select set_config('request.jwt.claims', '{"sub":"a1000000-0000-0000-0000-000000000001","role":"authenticated"}', true);
select is((select count(id)::integer from public.developer_apps), 1, 'owner sees own app');
reset role;
insert into public.developer_grants(id, app_id, user_id, scopes) values ('a3000000-0000-0000-0000-000000000001', 'a2000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000002', array['profile']);
insert into public.developer_codes(hash, grant_id, scopes, redirect_uri, challenge, expires_at) values (repeat('a',64), 'a3000000-0000-0000-0000-000000000001', array['profile'], 'https://example.org/cb', repeat('a',43), now() + interval '2 minutes');
insert into public.developer_tokens(access_hash, refresh_hash, grant_id, scopes, access_expires_at, refresh_expires_at) values (repeat('b',64), repeat('c',64), 'a3000000-0000-0000-0000-000000000001', array['profile'], now()+interval '10 minutes', now()+interval '1 day');
update public.developer_apps set enabled = false where id = 'a2000000-0000-0000-0000-000000000001';
select is((select count(*)::integer from public.developer_grants where app_id = 'a2000000-0000-0000-0000-000000000001'), 0, 'disabling atomically revokes grants');
select is((select count(*)::integer from public.developer_codes where hash = repeat('a',64)), 0, 'revocation removes codes');
select is((select count(*)::integer from public.developer_tokens where access_hash = repeat('b',64)), 0, 'revocation removes token pairs');
select throws_ok($$insert into public.developer_tokens(access_hash, refresh_hash, grant_id, scopes, access_expires_at, refresh_expires_at) values (repeat('d',64), repeat('e',64), 'a3000000-0000-0000-0000-000000000001', array['profile'], now(), now())$$, '23503', null, 'in-flight exchange cannot revive revoked grant');
select throws_ok($$insert into public.developer_apps(owner_id,name,description,contact_email,privacy_url,client_type,redirect_uris) values ('a1000000-0000-0000-0000-000000000001','Bad','Missing secret','a@example.org','https://example.org','confidential',array['https://example.org/cb'])$$, '23514', null, 'confidential clients require a secret hash');
select throws_ok($$insert into public.developer_grants(app_id,user_id,scopes) values ('a2000000-0000-0000-0000-000000000001','a1000000-0000-0000-0000-000000000002',array['profile'])$$, '23514', null, 'disabled app cannot acquire a new grant');
update public.developer_apps set enabled = true where id = 'a2000000-0000-0000-0000-000000000001';
insert into public.developer_grants(id, app_id, user_id, scopes) values ('a3000000-0000-0000-0000-000000000001', 'a2000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000002', array['profile']);
set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"a1000000-0000-0000-0000-000000000002","role":"authenticated"}', true);
select is((select count(id)::integer from public.developer_apps), 1, 'consenting member sees the authorized application metadata');
reset role;
insert into auth.users(id) values ('a1000000-0000-0000-0000-000000000003');
insert into public.user_profiles(id,email,is_admin) values ('a1000000-0000-0000-0000-000000000003','admin@example.org',true);
insert into public.developer_scope_requests(id,app_id,scopes,purpose) values ('a4000000-0000-0000-0000-000000000001','a2000000-0000-0000-0000-000000000001',array['groups'],'Group-specific lab equipment access.');
set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"a1000000-0000-0000-0000-000000000003","role":"authenticated"}', true);
select lives_ok($$select public.developer_review_scope('a4000000-0000-0000-0000-000000000001',true,'Necessary for lab equipment access.')$$, 'admin may approve requested scopes');
select ok((select 'groups' = any(approved_scopes) from public.developer_apps where id='a2000000-0000-0000-0000-000000000001'), 'approval changes the app scope allowlist');
select is((select reviewed_by from public.developer_scope_requests where id='a4000000-0000-0000-0000-000000000001'), 'a1000000-0000-0000-0000-000000000003'::uuid, 'reviewer is recorded from the authenticated session');
select throws_ok($$select public.developer_review_scope('a4000000-0000-0000-0000-000000000001',true,'Replay attempt')$$, '22023', null, 'review cannot be replayed');
reset role;
select is((select count(*)::integer from public.developer_grants where app_id='a2000000-0000-0000-0000-000000000001'), 0, 'scope changes invalidate previous consent');
select ok(not has_function_privilege('authenticated','public.developer_consume_refresh(text)','EXECUTE'), 'members cannot directly consume refresh tokens');
insert into public.developer_grants(id,app_id,user_id,scopes) values ('a3000000-0000-0000-0000-000000000001','a2000000-0000-0000-0000-000000000001','a1000000-0000-0000-0000-000000000002',array['profile']);
insert into public.developer_tokens(access_hash,refresh_hash,grant_id,scopes,access_expires_at,refresh_expires_at) values (repeat('f',64),repeat('a',64),'a3000000-0000-0000-0000-000000000001',array['profile'],now()+interval '10 minutes',now()+interval '1 day');
select ok(public.developer_consume_refresh(repeat('a',64)), 'refresh token is consumed once');
select ok((select refresh_used from public.developer_tokens where refresh_hash=repeat('a',64)), 'consumed refresh hash is retained for replay detection');
insert into public.developer_tokens(access_hash,refresh_hash,grant_id,scopes,access_expires_at,refresh_expires_at) values (repeat('b',64),repeat('c',64),'a3000000-0000-0000-0000-000000000001',array['profile'],now()+interval '10 minutes',now()+interval '1 day');
select ok(not public.developer_consume_refresh(repeat('a',64)), 'refresh reuse is rejected');
select is((select count(*)::integer from public.developer_tokens where grant_id='a3000000-0000-0000-0000-000000000001'), 0, 'refresh reuse revokes all descendant tokens');
select * from finish();
rollback;
